CREATE TABLE public.post_bell_interests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),post_id uuid NOT NULL,section text NOT NULL CHECK(section IN('work-wanted','work-offered','service-providers','service-wanted')),area text NOT NULL,need text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,post_id));
GRANT ALL ON public.post_bell_interests TO service_role;
ALTER TABLE public.post_bell_interests ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.capture_post_bell_interest() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN SELECT * INTO p FROM public.posts WHERE id=NEW.post_id AND module='job'; IF p.id IS NOT NULL THEN INSERT INTO public.post_bell_interests(user_id,post_id,section,area,need) VALUES(NEW.member_id,p.id,CASE WHEN p.service_type='service' THEN CASE WHEN p.kind='seeker' THEN 'service-wanted' ELSE 'service-providers' END ELSE CASE WHEN p.kind='seeker' THEN 'work-wanted' ELSE 'work-offered' END END,coalesce(p.location,''),coalesce(nullif(p.skill,''),p.title)) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER capture_post_bell_interest AFTER INSERT ON public.post_chat_pairs FOR EACH ROW EXECUTE FUNCTION public.capture_post_bell_interest();
INSERT INTO public.post_bell_interests(user_id,post_id,section,area,need) SELECT c.member_id,p.id,CASE WHEN p.service_type='service' THEN CASE WHEN p.kind='seeker' THEN 'service-wanted' ELSE 'service-providers' END ELSE CASE WHEN p.kind='seeker' THEN 'work-wanted' ELSE 'work-offered' END END,coalesce(p.location,''),coalesce(nullif(p.skill,''),p.title) FROM public.post_chat_pairs c JOIN public.posts p ON p.id=c.post_id WHERE p.module='job' ON CONFLICT DO NOTHING;
CREATE FUNCTION public.list_anonymous_bell_board(_section text) RETURNS TABLE(id uuid,source text,area text,need text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) OR NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF _section IN('goods','returns','cars') THEN RETURN QUERY SELECT d.id,'vehicle'::text, d.from_place||' → '||d.to_place,d.vehicle_type FROM public.vehicle_bell_demands d WHERE d.category=_section AND public.account_allowed(d.user_id) ORDER BY d.rang_at DESC; ELSE RETURN QUERY SELECT i.id,'post'::text,i.area,i.need FROM public.post_bell_interests i WHERE i.section=_section AND public.account_allowed(i.user_id) ORDER BY i.created_at DESC; IF _section='service-providers' THEN RETURN QUERY SELECT r.id,'service'::text,r.area,r.service FROM public.service_requests r WHERE public.account_allowed(r.user_id) ORDER BY r.created_at DESC; END IF; END IF; END $$;
REVOKE ALL ON FUNCTION public.list_anonymous_bell_board(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.list_anonymous_bell_board(text) TO authenticated;
CREATE FUNCTION public.open_anonymous_bell_chat(_id uuid,_source text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; original uuid; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) OR NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF _source='vehicle' THEN RETURN public.open_vehicle_demand_chat(_id); ELSIF _source='post' THEN SELECT user_id,post_id INTO target,original FROM public.post_bell_interests WHERE id=_id; ELSIF _source='service' THEN SELECT user_id INTO target FROM public.service_requests WHERE id=_id; END IF; IF target IS NULL OR target=auth.uid() OR NOT public.account_allowed(target) THEN RAISE EXCEPTION 'DEMAND_UNAVAILABLE'; END IF; INSERT INTO public.service_request_pairs(request_id,member_id,owner_id) VALUES(_id,auth.uid(),target) ON CONFLICT DO NOTHING; RETURN target; END $$;
REVOKE ALL ON FUNCTION public.open_anonymous_bell_chat(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.open_anonymous_bell_chat(uuid,text) TO authenticated;